return .{ .ok = .{ .width = i.width, .height = i.height, .pitch = i.pitch, .bpp = i.bpp } };

const stdin = std.fs.File.stdin();
var i: usize = 0;
while (i < $mod.readln_buf.len) {
    var b: [1]u8 = undefined;
    const n = stdin.read(b[0..]) catch return .{ .failed = "Failed to read stdin" };
    if (n == 0) {
        if (i == 0) return .{ .eof = .{} };
        return .{ .line = $mod.readln_buf[0..i] };
    }
    if (b[0] == '\n') {
        if (i > 0 and $mod.readln_buf[i - 1] == '\r') i -= 1;
        return .{ .line = $mod.readln_buf[0..i] };
    }
    $mod.readln_buf[i] = b[0];
    i += 1;
}
return .{ .failed = "line too long" };

